refs += [dict(id='full',title='Fine-Grained Derandomization: From Problem-Centric to Resource-Centric Complexity — full version',authors='Marco L. Carmosino; Russell Impagliazzo; Manuel Sabin',year=2018,url='https://eccc.weizmann.ac.il/report/2018/092/',pdf_url='https://eccc.weizmann.ac.il/report/2018/092/download/',locator='Dated 4 May 2018; Definitions 2.12–2.14, Theorems 3.4 and 3.9; Section 4; Appendix B, Theorem B.1.'),dict(id='typical',title='Pseudorandom generators, typically-correct derandomization, and circuit lower bounds',authors='Jeff Kinne; Dieter van Melkebeek; Ronen Shaltiel',year=2012,url='https://doi.org/10.1007/s00037-011-0019-z',pdf_url='https://pages.cs.wisc.edu/~dieter/Papers/r-typical-full.pdf',locator='Author manuscript dated 16 August 2010; Theorem 10 and Section 6.4 give lower-bound consequences under much smaller exceptional-input sets; journal publication 2012.'),dict(id='thesis',title='On The Utility of Fine-Grained Complexity Theory',authors='Manuel Sabin',year=2020,url='https://www2.eecs.berkeley.edu/Pubs/TechRpts/2020/EECS-2020-165.pdf',pdf_url='https://www2.eecs.berkeley.edu/Pubs/TechRpts/2020/EECS-2020-165.pdf',locator='Chapter 5, concluding question on page 86 repeats the inverse-polynomial-error converse question.')]
issue='The source does not specify the language class or explicit function to be proved hard, the Boolean or arithmetic circuit model, the lower-bound rate, or its infinitely-often/almost-everywhere quantifiers. It also discusses two different heuristic simulation premises without selecting which one is the antecedent of the requested converse. The uniform-distribution deterministic premise below is precisely recoverable, but choosing a particular circuit separation as its consequence would invent a conjecture. These choices are needed before a definitive benchmark implication and acceptance criterion can be certified.'
notes=['Recovered inverse-polynomial exceptional-input error and almost-everywhere simulation, distinguishing these from randomness error and infinitely-often guarantees.','Defined the deterministic uniform-distribution premise with all language, error, algorithm and length quantifiers.','Separated the paper’s second randomness-reduced premise and its proved uniform time-class consequence from a nonuniform circuit lower bound.','Read the earlier typical-correctness lower-bound theorem and the 2020 author thesis; retained the missing target-class/model/rate issue instead of inventing a circuit conjecture.']
save(i,dict(title='Circuit lower bounds from inverse-polynomial-error heuristics',
 formal='What nonuniform circuit lower bounds follow from the efficient, almost-everywhere heuristic simulations of BPP obtained in the source? One precisely defined premise is (BPP,U)⊆HeurP: for every language L∈BPP and every integer k≥1, there is a deterministic polynomial-time algorithm A_{L,k} and an integer N_{L,k} such that, for every n≥N_{L,k}, at most a fraction n⁻ᵏ of strings x∈{0,1}ⁿ satisfy A_{L,k}(x)≠1_L(x). The source also obtains randomness-reduced heuristics over efficiently samplable distributions. It asks for a circuit-lower-bound consequence but does not identify a target circuit class, hard language class or growth rate. Thus this remains a research direction requiring a specified conclusion and a choice of premise, rather than a complete implication ready for proof.',
 definitions='''A language is a subset L⊆{0,1}*, with membership indicator 1_L. BPP consists of languages decided by one uniform randomized Turing machine in time polynomial in input length on every input and random tape, with probability of the correct bit at least 2/3 on each input. Its random bits are independent and fair. U_n is the uniform distribution on all 2ⁿ strings of length n. A deterministic polynomial-time heuristic has one finite program, no advice and a worst-case polynomial running-time bound; its only errors arise from the subset of inputs it answers incorrectly. In the displayed premise the algorithm and its polynomial exponent may depend on L and k, but not on n; the statement does not require one algorithm running in time polynomial jointly in n and k, nor one polynomial exponent for all languages and requested errors. Almost everywhere means every sufficiently large input length, with a threshold permitted to depend on L,k. Infinitely often instead means merely infinitely many lengths and is a weaker guarantee. No correctness promise is imposed on the finitely many excluded lengths. The fraction n⁻ᵏ is measured over inputs, not over the random bits of a simulation. In the source’s randomness-reduced variant, for each fixed α>0 the simulation uses at most n^α coins in polynomial time and may fail the usual 2/3 per-input correctness requirement only on an inverse-polynomial measure of inputs under the chosen samplable ensemble. The source quantifies over polynomial-time samplers for distribution ensembles; these are a different premise from a deterministic simulation only under U. The choice between the two premises is not resolved by the excerpt.

For comparison, an ordinary nonuniform Boolean circuit on n bits is a finite acyclic network of Boolean gates, such as fan-in-two AND/OR and unary NOT, with one output; a separate circuit is allowed at each n without a uniform construction algorithm. P/poly is the class of languages with such exact circuits of size n^{O(1)}. Arithmetic circuits instead compute polynomials using field operations and have a different output and cost model. A circuit lower bound must specify which of these or another model is meant, which function or language family is hard, the required size as a function of its own input parameter, and the lengths on which it holds. These are examples of missing mathematical choices, not a selection of the conjecture for this card.''',
 question_type='yes_no',answer_criterion='A completed formulation must select a precise heuristic-simulation assumption and a particular nonuniform circuit lower-bound conclusion, then prove or refute that implication. The source’s request for any circuit lower bounds does not presently supply a fixed acceptance predicate. Known lower bounds unrelated to the assumption, uniform time hierarchies, or results assuming a much smaller fraction of bad inputs do not by themselves complete this intended converse.',
 context_blocks=[dict(title='From concrete hardness to average-case simulation',text='The source derives deterministic polynomial-time heuristics under the uniform distribution, and small-randomness polynomial-time heuristics under efficiently samplable distributions, from moderate counting hardness for k-Orthogonal Vectors or k-Clique. The converse question asks what circuit hardness follows from the simulation guarantees themselves; it does not simply retain the original fine-grained hardness conjecture as an extra premise.',citation='primary'),dict(title='A uniform converse is already proved',text='Appendix B proves that even infinitely-often deterministic polynomial-time heuristics with at most one-third bad inputs under U imply DTIME(t)⊄BPP for every time-constructible superpolynomial t. Here time-constructible means the bound can be computed within O(t(n)) time, and superpolynomial means it eventually exceeds nᶜ for every constant c. This separates uniform machine classes; it is not a lower bound against nonuniform circuits.',citation='full'),dict(title='Much smaller exceptional sets have known circuit consequences',text='Kinne, van Melkebeek and Shaltiel’s Theorem 10 in the checked manuscript assumes subexponential-time nondeterministic arithmetic-circuit identity tests making errors on at most 2^{n^ε} length-n encodings, for every ε>0. It concludes that either NEXP lacks polynomial-size Boolean circuits or the permanent lacks polynomial-size arithmetic circuits. That is a bound on the number of exceptional encodings, not an allowance of an inverse-polynomial fraction of all 2ⁿ inputs.',citation='typical'),dict(title='The broad converse remains broad in later exposition',text='Sabin’s 2020 dissertation repeats the question for inverse-polynomial-error heuristics. The passage does not choose a language class, circuit model or target rate. The present formulation therefore preserves the premise and motivation while identifying the missing conclusion.',citation='thesis')],
 why='Would clarify whether substantially weakening derandomization to allow a small set of bad inputs still forces nonuniform computational hardness. It probes the reach of the hardness-versus-randomness connection beyond exact or extremely low-error simulations.',
 references=refs,progress=[dict(date='2012',text='Typical-correctness simulations with far smaller exceptional sets are shown to imply a Boolean-or-arithmetic circuit lower-bound disjunction.',citation='typical'),dict(date='2018',text='The source obtains almost-everywhere inverse-polynomial-error heuristics from fine-grained hardness and proves a uniform time-class converse, leaving circuit consequences open.',citation='primary'),dict(date='2020',text='The author’s dissertation repeats the inverse-polynomial-error converse question.',citation='thesis')],
 status='uncertain',status_note='Read the source and full version, including Appendix B, and the relevant earlier lower-bound theorem; checked the 2020 dissertation and subsequent-work searches through 12 September 2026. No source recovered a single specified circuit-lower-bound conclusion for this broad question. Later algorithms-to-lower-bounds results have their own simulation or circuit-testing assumptions and cannot be treated as a resolution merely from a similar title.',model_self_contained=False,requires_context=True,statement_review=dict(status='needs_specification',reviewed_on=DATE,notes=notes,remaining_issue=issue),review_note=issue,
 importance=dict(score=c['importance']['score'],method='editorial',reason='Addresses the scope of a foundational connection between derandomization and nonuniform hardness; the lower-bound target must still be specified before it is a usable benchmark implication. Existing score retained.',assessed_on=DATE),
 working_summary=dict(sentences=['The source obtains polynomial-time simulations of BPP that err on at most an inverse-polynomial fraction of inputs at every sufficiently large length.','For the deterministic version the input distribution is uniform, and a separate algorithm is allowed for each desired inverse-polynomial error rate.','It asks whether such simulation guarantees imply circuit lower bounds.','The known converse separates uniform time classes, while older nonuniform lower-bound consequences require much smaller exceptional-input sets.','The desired hard language class, circuit model, lower-bound rate and exact simulation premise remain to be specified.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full','typical','thesis'])
),notes=notes,checked_sources=[r['url'] for r in refs]+['https://chen-lijie.github.io/'],state='improved_unfinished')
